package com.mideyy7.retrieve.search

import kotlinx.serialization.json.Json
import kotlinx.serialization.json.int
import kotlinx.serialization.json.jsonArray
import kotlinx.serialization.json.jsonObject
import kotlinx.serialization.json.jsonPrimitive
import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test
import java.io.File

/**
 * Token-id parity with HuggingFace: every case in tokenizer_fixture.json (generated by
 * ml/tools/make_tokenizer_fixture.py from the deployed model's tokenizer) must produce exactly the
 * same ids. A single mismatch means the phone would embed different text than the laptop evaluated.
 */
class WordPieceTokenizerTest {
    private val vocab = File("src/main/assets/embedding/vocab.txt").readLines()
    private val tokenizer = WordPieceTokenizer(vocab, maxLen = 128)

    private val fixture = Json.parseToJsonElement(
        requireNotNull(javaClass.classLoader!!.getResource("tokenizer_fixture.json")).readText(),
    ).jsonObject

    @Test
    fun matchesHuggingFaceOnEveryFixtureCase() {
        val cases = fixture["cases"]!!.jsonArray
        assertEquals(fixture["vocab_size"]!!.jsonPrimitive.int, vocab.size)
        val failures = cases.mapNotNull { c ->
            val text = c.jsonObject["text"]!!.jsonPrimitive.content
            val expected = c.jsonObject["ids"]!!.jsonArray.map { it.jsonPrimitive.int }
            val actual = tokenizer.encode(text).toList()
            if (actual == expected) null else "${text.take(60)}\n   expected $expected\n   actual   $actual"
        }
        assertTrue("${failures.size}/${cases.size} cases differ:\n" + failures.take(5).joinToString("\n"), failures.isEmpty())
        assertTrue("fixture should be substantial", cases.size >= 400)
    }

    @Test
    fun paddingAndMask() {
        val (ids, mask) = tokenizer.encodePadded("unit propagation")
        val real = tokenizer.encode("unit propagation")
        assertEquals(128, ids.size)
        assertEquals(real.toList(), ids.take(real.size))
        assertTrue(ids.drop(real.size).all { it == tokenizer.pad })
        assertEquals(real.size, mask.sum())
    }
}
